import './App.css';
import { Routes, Route } from 'react-router-dom';
import React from 'react';

import Header from './components/Header/Header';
import Work from './pages/Work/Work';

function App() {
  return (
    <div className="body">
      <Header />

      <Routes>
        <Route exact path="/" element={<Work />} />

        <Route exact path="*" element={<Work />} />
      </Routes>
    </div>
  );
}

export default App;
